BEGIN;
-- Historial inicial, extraído del generador de JavaScript. Se usa una tabla temporal para comprimir las filas.
-- Cada alumno ocupa dos caracteres: estado P/A/T/R/J y minuto de entrada relativo al comienzo del turno.
-- Los pares -- indican que no había registro (por ejemplo, ECPA para alumnos de otros años).
-- Las horas de tarde inválidas 13:60–13:69 del generador original se normalizan a 14:00–14:09.
CREATE TEMP TABLE et35_historial_inicial (fecha date PRIMARY KEY, datos text NOT NULL) ON COMMIT DROP;


WITH registros AS (
 SELECT a.id AS alumno_id, h.fecha, t.nombre AS turno, t.inicio, t.fin,
 substring(h.datos FROM (2*a.id-1)::integer FOR 1) AS marca,
 ascii(substring(h.datos FROM (2*a.id)::integer FOR 1))-65 AS minuto
 FROM et35_historial_inicial h CROSS JOIN public.alumnos a
 JOIN public.cursos c ON c.codigo=a.curso_codigo
 JOIN public.turnos t ON t.nombre=c.turno
 WHERE a.id BETWEEN 1 AND 2175 AND substring(h.datos FROM (2*a.id-1)::integer FOR 1) <> '-'
)
SELECT -(to_char(fecha,'YYYYMMDD')::bigint*10000+alumno_id), alumno_id,fecha,'principal',
 CASE WHEN marca IN ('A','J') THEN NULL ELSE (inicio + minuto*interval '1 minute')::time END,
 CASE WHEN marca IN ('A','J') THEN NULL WHEN marca='R' THEN CASE turno WHEN 'Noche' THEN time '20:00' WHEN 'Tarde' THEN time '16:00' ELSE time '10:30' END ELSE fin END,
 CASE marca WHEN 'P' THEN 'Presente' WHEN 'A' THEN 'Ausente' WHEN 'T' THEN 'Tarde' WHEN 'R' THEN 'Retiro' WHEN 'J' THEN 'Justificado' END,
 CASE marca WHEN 'A' THEN 'Sistema' WHEN 'J' THEN 'Justificación' WHEN 'R' THEN 'Manual' ELSE 'QR' END, true
FROM registros ON CONFLICT DO NOTHING;
COMMIT;
